using System.Collections.Generic;
using Astrea.RunModifiers;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "DicesRewardsListsList", menuName = "Data/Battle/Dice System/DicesRewardsLists Lists")]
public class DicesRewardsListsList : ScriptableObject
{
	[Header("Lists")]
	[SerializeField]
	private DicesRewardsList[] dicesRewardsLists;

	[Header("Starter Tier")]
	[SerializeField]
	private DiceTier starterTier;

	[SerializeField]
	private DiceTier hexTier;

	[Header("Progression System")]
	[SerializeField]
	private Character[] characters;

	[SerializeField]
	private Character anyCharacter;

	[SerializeField]
	private DiceTier[] diceTiers;

	[SerializeField]
	private SaveSystem saveSystem;

	[SerializeField]
	private AllPlayerDicesList allPlayerDicesList;

	[SerializeField]
	private GameController gameController;

	[Header("Runtime")]
	[SerializeField]
	private DiceTierDiceList[] currentCharacterUnlockedDiceTierDiceList;

	[SerializeField]
	private DiceTierDiceList[] anyCharacterUnlockedDiceTierDiceList;

	[SerializeField]
	private List<Dice> tutorialDice = new List<Dice>();

	[SerializeField]
	private List<Dice> hexDice = new List<Dice>();

	[SerializeField]
	private List<Dice> cantBePickedAsRewardDice = new List<Dice>();

	public List<string> DiscoveredDice = new List<string>();

	public DicesRewardsList GetDiceRewardsList(Character character)
	{
		for (int i = 0; i < dicesRewardsLists.Length; i++)
		{
			if (dicesRewardsLists[i].Character == character)
			{
				return dicesRewardsLists[i];
			}
		}
		return null;
	}

	public void PopulateAnyAndCurrentCharacterUnlockedDiceTierDiceList(bool dailyRun = false)
	{
		if (!dailyRun)
		{
			PopulateLockedDice();
		}
		currentCharacterUnlockedDiceTierDiceList = new DiceTierDiceList[diceTiers.Length];
		for (int i = 0; i < currentCharacterUnlockedDiceTierDiceList.Length; i++)
		{
			currentCharacterUnlockedDiceTierDiceList[i] = new DiceTierDiceList(diceTiers[i]);
		}
		DiceTierDiceList[] characterUnlockedDicesRewardsList = GetCharacterUnlockedDicesRewardsList(ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter, dailyRun);
		for (int j = 0; j < currentCharacterUnlockedDiceTierDiceList.Length; j++)
		{
			currentCharacterUnlockedDiceTierDiceList[j].diceList.AddRange(characterUnlockedDicesRewardsList[j].diceList.Duplicate());
		}
		anyCharacterUnlockedDiceTierDiceList = new DiceTierDiceList[diceTiers.Length];
		for (int k = 0; k < anyCharacterUnlockedDiceTierDiceList.Length; k++)
		{
			anyCharacterUnlockedDiceTierDiceList[k] = new DiceTierDiceList(diceTiers[k]);
		}
		DiceTierDiceList[] characterUnlockedDicesRewardsList2 = GetCharacterUnlockedDicesRewardsList(anyCharacter, dailyRun);
		for (int l = 0; l < anyCharacterUnlockedDiceTierDiceList.Length; l++)
		{
			anyCharacterUnlockedDiceTierDiceList[l].diceList.AddRange(characterUnlockedDicesRewardsList2[l].diceList.Duplicate());
		}
		MuteDiceForRunModifiers(currentCharacterUnlockedDiceTierDiceList, dailyRun);
		MuteDiceForRunModifiers(anyCharacterUnlockedDiceTierDiceList, dailyRun);
		CheckStarterDiceDiscovered();
	}

	private void MuteDiceForRunModifiers(DiceTierDiceList[] diceTierDiceLists, bool dailyRun)
	{
		List<RunModifier> list = new List<RunModifier>();
		if (GameScenesUtils.IsBattleScene())
		{
			list = ReferenceSingleton<AssetsReference>.Instance.RunModifiersHandler.ActiveRunModifiers;
		}
		else if (dailyRun)
		{
			list = ReferenceSingleton<AssetsReference>.Instance.DailyRunHandler.DailyRunRunModifiers;
		}
		else
		{
			list.AddRange(ModifiersPanel.Instance.GetRunCustomizationActiveRunModifiers());
		}
		for (int i = 0; i < list.Count; i++)
		{
			RunModifier activeRunModifier = list[i];
			for (int j = 0; j < diceTierDiceLists.Length; j++)
			{
				diceTierDiceLists[j].diceList.RemoveAll(delegate(Dice die)
				{
					for (int k = 0; k < activeRunModifier.DiceToMute.Count; k++)
					{
						if (die.DiceName.Replace(" ", "").Contains(activeRunModifier.DiceToMute[k].Replace(" ", "")))
						{
							return true;
						}
					}
					return false;
				});
			}
		}
	}

	public void PopulateLockedDice()
	{
		if (gameController.IsDemo)
		{
			return;
		}
		List<DiceFace> list = new List<DiceFace>();
		List<string> list2 = new List<string>();
		for (int i = 0; i < characters.Length; i++)
		{
			list.AddRange(characters[i].GetLockedDiceFaces());
			list2.AddRange(characters[i].GetLockedDiceNames());
		}
		for (int j = 0; j < list.Count; j++)
		{
			DiceFace diceFaceToCheck = list[j];
			for (int k = 0; k < dicesRewardsLists.Length; k++)
			{
				List<Dice> allDice = dicesRewardsLists[k].GetAllDice();
				for (int l = 0; l < allDice.Count; l++)
				{
					Dice dice = allDice[l];
					if (CheckIfDieHasDiceFace(dice, diceFaceToCheck))
					{
						(dice as PlayerDice).SetCompendiumItemState(CompendiumItemState.Locked);
					}
				}
			}
		}
		for (int m = 0; m < list2.Count; m++)
		{
			string text = list2[m];
			for (int n = 0; n < dicesRewardsLists.Length; n++)
			{
				List<Dice> allDice2 = dicesRewardsLists[n].GetAllDice();
				for (int num = 0; num < allDice2.Count; num++)
				{
					PlayerDice playerDice = allDice2[num] as PlayerDice;
					if (playerDice.CompendiumItemState != CompendiumItemState.Locked && playerDice.DiceName.Replace(" ", "").Replace("+", "") == text.Replace(" ", ""))
					{
						playerDice.SetCompendiumItemState(CompendiumItemState.Locked);
					}
				}
			}
		}
	}

	private bool CheckIfDieHasDiceFace(Dice dice, DiceFace diceFaceToCheck)
	{
		DiceFace diceFace = dice.GetDiceFaces().First();
		if (diceFaceToCheck.EnableSecondAction)
		{
			bool flag = false;
			bool flag2 = false;
			if (diceFaceToCheck.BattleAction == diceFace.BattleAction)
			{
				flag = true;
			}
			if (diceFace.EnableSecondAction && diceFaceToCheck.SecondBattleAction == diceFace.SecondBattleAction)
			{
				flag2 = true;
			}
			if (flag && flag2)
			{
				return true;
			}
		}
		else
		{
			if (diceFaceToCheck.BattleAction == diceFace.BattleAction)
			{
				return true;
			}
			if (diceFace.EnableSecondAction && diceFaceToCheck.BattleAction == diceFace.SecondBattleAction)
			{
				return true;
			}
		}
		return false;
	}

	private DiceTierDiceList[] GetCharacterUnlockedDicesRewardsList(Character character, bool dailyRun)
	{
		DiceTierDiceList[] array = new DiceTierDiceList[diceTiers.Length];
		for (int i = 0; i < array.Length; i++)
		{
			array[i] = new DiceTierDiceList(diceTiers[i]);
		}
		DiceTierDiceList[] diceTierDiceLists = GetDiceRewardsList(character).DiceTierDiceLists;
		for (int j = 0; j < array.Length; j++)
		{
			array[j].diceList = diceTierDiceLists[j].diceList.Duplicate();
		}
		DiceTierDiceList[] diceTierDiceListsMods = GetDiceRewardsList(character).DiceTierDiceListsMods;
		for (int k = 0; k < array.Length; k++)
		{
			for (int l = 0; l < diceTierDiceListsMods.Length; l++)
			{
				if (array[k].tier == diceTierDiceListsMods[l].tier)
				{
					array[k].diceList.AddRange(diceTierDiceListsMods[l].diceList);
				}
			}
		}
		for (int m = 0; m < array.Length; m++)
		{
			array[m].diceList.RemoveAll(delegate(Dice die)
			{
				PlayerDice playerDice = die as PlayerDice;
				if (dailyRun)
				{
					return playerDice.Mod;
				}
				return playerDice.CompendiumItemState == CompendiumItemState.Locked || playerDice.MuteForMod;
			});
		}
		return array;
	}

	private void CheckStarterDiceDiscovered()
	{
		List<InventoryItem> defaultInventoryItems = ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterDice.DefaultInventoryItems;
		List<Dice> list = new List<Dice>();
		for (int i = 0; i < defaultInventoryItems.Count; i++)
		{
			PlayerDice playerDice = defaultInventoryItems[i].dice as PlayerDice;
			if (playerDice.CompendiumItemState == CompendiumItemState.Undiscovered || playerDice.CompendiumItemState == CompendiumItemState.Locked)
			{
				list.Add(defaultInventoryItems[i].dice);
			}
		}
		if (list.Count > 0)
		{
			DiceDiscovered(list, dontGetOtherTiersDiscover: true);
		}
	}

	public void LoadDiscoveredDice()
	{
		saveSystem.LoadDiscoveredDice();
		List<Dice> dice = allPlayerDicesList.dice;
		for (int i = 0; i < dice.Count; i++)
		{
			PlayerDice playerDice = dice[i] as PlayerDice;
			if (playerDice.CompendiumItemState != CompendiumItemState.Locked)
			{
				if (DiscoveredDice.Contains(GetDieNameWithoutPlusAndSpaces(playerDice)))
				{
					playerDice.SetCompendiumItemState(CompendiumItemState.Discovered);
				}
				else
				{
					playerDice.SetCompendiumItemState(CompendiumItemState.Undiscovered);
				}
			}
		}
	}

	public void DiceDiscovered(List<Dice> dice, bool dontGetOtherTiersDiscover)
	{
		if (gameController.IsDemo)
		{
			return;
		}
		List<Dice> list = new List<Dice>();
		for (int i = 0; i < dice.Count; i++)
		{
			PlayerDice playerDice = dice[i] as PlayerDice;
			if (playerDice.CompendiumItemState == CompendiumItemState.Discovered)
			{
				continue;
			}
			if (!dontGetOtherTiersDiscover)
			{
				List<Dice> diceFromAllTierWithSameDiceType = GetDiceFromAllTierWithSameDiceType(GetDieNameWithoutPlusAndSpaces(playerDice), currentCharacterUnlockedDiceTierDiceList);
				if (diceFromAllTierWithSameDiceType.Count == 0)
				{
					diceFromAllTierWithSameDiceType = GetDiceFromAllTierWithSameDiceType(GetDieNameWithoutPlusAndSpaces(playerDice), anyCharacterUnlockedDiceTierDiceList);
				}
				list.AddRange(diceFromAllTierWithSameDiceType);
			}
			else
			{
				list.Add(playerDice);
			}
			DiscoveredDice.AddIfNotAlreadyOnList(GetDieNameWithoutPlusAndSpaces(playerDice));
		}
		for (int j = 0; j < list.Count; j++)
		{
			(list[j] as PlayerDice).SetCompendiumItemState(CompendiumItemState.Discovered);
		}
		saveSystem.SaveDiscoveredDice(saveAndStoreCache: true);
	}

	private List<Dice> GetDiceFromAllTierWithSameDiceType(string diceTypeName, DiceTierDiceList[] diceTierDiceLists)
	{
		List<Dice> list = new List<Dice>();
		foreach (DiceTierDiceList diceTierDiceList in diceTierDiceLists)
		{
			for (int j = 0; j < diceTierDiceList.diceList.Count; j++)
			{
				Dice dice = diceTierDiceList.diceList[j];
				if (GetDieNameWithoutPlusAndSpaces(dice) == diceTypeName)
				{
					list.Add(dice);
				}
			}
		}
		return list;
	}

	public void DiceFacesDiscovered(DiceFace[] diceFaces)
	{
		List<Dice> list = new List<Dice>();
		for (int i = 0; i < diceFaces.Length; i++)
		{
			List<Dice> diceFromAllTierWithSameDiceFaceForDiscoveredDice = GetDiceFromAllTierWithSameDiceFaceForDiscoveredDice(diceFaces[i], GetDiceRewardsList(ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter).DiceTierDiceLists);
			if (diceFromAllTierWithSameDiceFaceForDiscoveredDice.Count == 0)
			{
				diceFromAllTierWithSameDiceFaceForDiscoveredDice = GetDiceFromAllTierWithSameDiceFaceForDiscoveredDice(diceFaces[i], GetDiceRewardsList(ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.AnyCharacter).DiceTierDiceLists);
			}
			list.AddRange(diceFromAllTierWithSameDiceFaceForDiscoveredDice);
			DiscoveredDice.Add(GetDieNameWithoutPlusAndSpaces(diceFromAllTierWithSameDiceFaceForDiscoveredDice.First()));
		}
		for (int j = 0; j < list.Count; j++)
		{
			(list[j] as PlayerDice).SetCompendiumItemState(CompendiumItemState.Discovered);
		}
		saveSystem.SaveDiscoveredDice(saveAndStoreCache: true);
	}

	private List<Dice> GetDiceFromAllTierWithSameDiceFaceForDiscoveredDice(DiceFace diceFace, DiceTierDiceList[] diceTierDiceLists)
	{
		List<Dice> list = new List<Dice>();
		for (int i = 0; i < diceTierDiceLists.Length; i++)
		{
			List<Dice> diceList = diceTierDiceLists[i].diceList;
			for (int j = 0; j < diceList.Count; j++)
			{
				Dice dice = diceList[j];
				if (CheckIfDieHasDiceFace(dice, diceFace))
				{
					list.Add(dice);
				}
			}
		}
		return list;
	}

	private string GetDieNameWithoutPlusAndSpaces(Dice die)
	{
		return die.DiceName.Replace("+", "").Replace(" ", "");
	}

	public void SetAllDiceToDiscovered()
	{
		DiscoveredDice.Clear();
		List<Dice> dice = allPlayerDicesList.dice;
		for (int i = 0; i < dice.Count; i++)
		{
			PlayerDice playerDice = dice[i] as PlayerDice;
			playerDice.SetCompendiumItemState(CompendiumItemState.Discovered);
			DiscoveredDice.AddIfNotAlreadyOnList(GetDieNameWithoutPlusAndSpaces(playerDice));
		}
		saveSystem.SaveDiscoveredDice(saveAndStoreCache: true);
	}

	public void SetAllDiceToUndiscoveredOrLocked()
	{
		SetAllDiceToUndiscovered();
		PopulateLockedDice();
		DiscoveredDice.Clear();
		saveSystem.SaveDiscoveredDice(saveAndStoreCache: true);
	}

	public void SetAllDiceToUndiscovered()
	{
		List<Dice> dice = allPlayerDicesList.dice;
		for (int i = 0; i < dice.Count; i++)
		{
			(dice[i] as PlayerDice).SetCompendiumItemState(CompendiumItemState.Undiscovered);
		}
	}

	public DiceTierDiceList GetCurrentCharacterUnlockedDiceTierDiceList(DiceTier diceTier)
	{
		for (int i = 0; i < currentCharacterUnlockedDiceTierDiceList.Length; i++)
		{
			if (currentCharacterUnlockedDiceTierDiceList[i].tier == diceTier)
			{
				return currentCharacterUnlockedDiceTierDiceList[i];
			}
		}
		return null;
	}

	public DiceTierDiceList GetAnyCharacterUnlockedDiceTierDiceList(DiceTier diceTier)
	{
		for (int i = 0; i < anyCharacterUnlockedDiceTierDiceList.Length; i++)
		{
			if (anyCharacterUnlockedDiceTierDiceList[i].tier == diceTier)
			{
				return anyCharacterUnlockedDiceTierDiceList[i];
			}
		}
		return null;
	}

	public List<Dice> GetAllUnlockedDiceButTierCurrentCharacter(DiceTier diceTier)
	{
		List<Dice> list = new List<Dice>();
		for (int i = 0; i < currentCharacterUnlockedDiceTierDiceList.Length; i++)
		{
			if (!(currentCharacterUnlockedDiceTierDiceList[i].tier == starterTier) && currentCharacterUnlockedDiceTierDiceList[i].tier != diceTier)
			{
				list.AddRange(currentCharacterUnlockedDiceTierDiceList[i].diceList);
			}
		}
		return list;
	}

	public List<Dice> GetAllUnlockedDiceButTierAnyCharacter(DiceTier diceTier)
	{
		List<Dice> list = new List<Dice>();
		for (int i = 0; i < anyCharacterUnlockedDiceTierDiceList.Length; i++)
		{
			if (anyCharacterUnlockedDiceTierDiceList[i].tier != diceTier)
			{
				list.AddRange(anyCharacterUnlockedDiceTierDiceList[i].diceList);
			}
		}
		return list;
	}

	public List<Dice> GetAllUnlockedDiceCurrentCharacter()
	{
		List<Dice> list = new List<Dice>();
		for (int i = 0; i < currentCharacterUnlockedDiceTierDiceList.Length; i++)
		{
			if (!(currentCharacterUnlockedDiceTierDiceList[i].tier == starterTier))
			{
				list.AddRange(currentCharacterUnlockedDiceTierDiceList[i].diceList);
			}
		}
		return list;
	}

	public List<Dice> GetAllUnlockedDiceAnyCharacter()
	{
		List<Dice> list = new List<Dice>();
		for (int i = 0; i < anyCharacterUnlockedDiceTierDiceList.Length; i++)
		{
			list.AddRange(anyCharacterUnlockedDiceTierDiceList[i].diceList);
		}
		return list;
	}

	public Dice GetOriginalDice(Dice dice)
	{
		string text = dice.name.Replace("(Clone)", "").ToLower();
		if (dice.DiceTier != hexTier)
		{
			List<Dice> diceList = GetCurrentCharacterUnlockedDiceTierDiceList(dice.DiceTier).diceList;
			for (int i = 0; i < diceList.Count; i++)
			{
				Dice dice2 = diceList[i];
				if (text == dice2.name.ToLower())
				{
					return dice2;
				}
			}
			List<Dice> diceList2 = GetAnyCharacterUnlockedDiceTierDiceList(dice.DiceTier).diceList;
			for (int j = 0; j < diceList2.Count; j++)
			{
				Dice dice3 = diceList2[j];
				if (text == dice3.name.ToLower())
				{
					return dice3;
				}
			}
		}
		for (int k = 0; k < tutorialDice.Count; k++)
		{
			Dice dice4 = tutorialDice[k];
			if (text == dice4.name.ToLower())
			{
				return dice4;
			}
		}
		for (int l = 0; l < hexDice.Count; l++)
		{
			Dice dice5 = hexDice[l];
			if (text == dice5.name.ToLower())
			{
				return dice5;
			}
		}
		for (int m = 0; m < cantBePickedAsRewardDice.Count; m++)
		{
			Dice dice6 = cantBePickedAsRewardDice[m];
			if (text == dice6.name.ToLower())
			{
				return dice6;
			}
		}
		return null;
	}

	public void PopulateDiceTierDiceListsMods(List<PlayerDice> diceMods)
	{
		for (int i = 0; i < dicesRewardsLists.Length; i++)
		{
			dicesRewardsLists[i].PopulateDiceTierDiceListsMods(diceMods);
		}
	}

	public void ClearDiceTierDiceListsMods()
	{
		for (int i = 0; i < dicesRewardsLists.Length; i++)
		{
			dicesRewardsLists[i].ClearDiceTierDiceListsMods(diceTiers);
		}
	}
}
